# ❌ OLD: Using full metaclass inheritance for simple subclass validation
# causes metaclass conflicts if multiple parent classes use different metaclasses.
class ValidatorMeta(type):
  def __new__(cls, name, bases, dct):
    if 'table_name' not in dct and name != 'BaseModel':
      raise TypeError(f"{name} must define 'table_name' attribute!")
    return super().__new__(cls, name, bases, dct)

class BaseModel(metaclass=ValidatorMeta):
  pass

# ✅ NEW: __init_subclass__ (Python 3.6+) handles subclass validation and registration
# cleanly without creating custom metaclasses or risking metaclass conflicts.
class BaseModel:
  def __init_subclass__(cls, table_name: str | None = None, **kwargs):
    super().__init_subclass__(**kwargs)
    if table_name is None:
      raise TypeError(f"{cls.__name__} must specify a 'table_name' argument!")
    cls._table = table_name

# Clean, declarative subclass definition:
class User(BaseModel, table_name='users'):
  id: int
  name: string
